import React, { FunctionComponent } from 'react';
import classNames from 'classnames';
import Text from '../text';
import './index.less';
import { SizeEnum, WeightEnum } from '../../types';
import IncreaseIconSVG from './increaseIcon.svg';
import DecreaseIconSVG from './decreaseIcon.svg';

interface PotentialCostSavingProps {
  className?: string;
  type?: keyof typeof PotentialCostSavingTypeOptions;
  costSavingNumber?: string;
}

const PotentialCostSavingTypeOptions = {
  decrease: 'decrease-type',
  increase: 'increase-type',
};

const PotentialCostSaving: FunctionComponent<PotentialCostSavingProps> = ({
  className,
  type = 'decrease',
  costSavingNumber,
}) => {
  return (
    <div
      className={classNames(
        'potential-cost-saving',
        className,
        PotentialCostSavingTypeOptions[type],
      )}
    >
      <Text
        className={classNames('cost-saving-number', PotentialCostSavingTypeOptions[type])}
        size={SizeEnum['12px']}
        weight={WeightEnum.semibold}
        text={`$${costSavingNumber}`}
      />
      {type === 'decrease' ? <img src={DecreaseIconSVG} /> : <img src={IncreaseIconSVG} />}
    </div>
  );
};

export default PotentialCostSaving;
